const body = $json.body ?? $json;
const sessionId = String(body.session_id ?? body.call_id ?? '').trim();
const clientRef = String(body.client_ref ?? '').trim();
const caller = String(body.caller ?? body.from ?? '').trim();
const query = String(body.query ?? body.question ?? body.text ?? '').trim();
const topKRaw = Number(body.top_k ?? 6);
const topK = Number.isFinite(topKRaw) ? Math.min(Math.max(Math.trunc(topKRaw), 1), 12) : 6;

return [{
  session_id: sessionId,
  client_ref: clientRef,
  caller,
  query,
  top_k: topK,
  request_ts: new Date().toISOString(),
}];

const input = $json || {};
const payload = input.context_payload ?? null;
const hasPayload = !!payload;
const errorObj = input.error ?? null;

const fallback = {
  session_id: String(input.session_id || ''),
  client_ref: String(input.client_ref || ''),
  caller: String(input.caller || ''),
  query: String(input.query || ''),
  history: [],
  memory_facts: [],
  source_links: [],
  knowledge_chunks: [],
  script_steps: [],
};

return [{
  ok: true,
  tool: 'context_fetch',
  source: hasPayload ? 'postgres' : 'fallback',
  context: hasPayload ? payload : fallback,
  warning: hasPayload ? '' : 'Postgres недоступен. Проверь credential Postgres Memory Agent (host/DNS/network).',
  error_info: hasPayload ? null : errorObj,
  hint: 'PII хранится во внешнем источнике. Для карточки клиента используй source_links и внешний коннектор (Google/CRM).',
}];

